import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.Arrays;

public class Main {

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static class Rect {
        int x1, y1, x2, y2;

        public Rect(int x1, int y1, int x2, int y2) {
            this.x1 = Math.min(x1, x2);
            this.x2 = Math.max(x1, x2);
            this.y1 = Math.min(y1, y2);
            this.y2 = Math.max(y1, y2);
        }

        // Calcula a menor distância de Manhattan entre dois retângulos
        public long distTo(Rect other) {
            long dx = Math.max(0, Math.max(this.x1, other.x1) - Math.min(this.x2, other.x2));
            long dy = Math.max(0, Math.max(this.y1, other.y1) - Math.min(this.y2, other.y2));
            return dx + dy;
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        String token = fs.next();
        if (token == null) return;

        int xi = Integer.parseInt(token);
        int yi = fs.nextInt();
        int xf = fs.nextInt();
        int yf = fs.nextInt();

        int n = fs.nextInt();

        int totalNodes = n + 2;
        Rect[] rects = new Rect[totalNodes];

        // Vértice 0: Ponto inicial
        rects[0] = new Rect(xi, yi, xi, yi);

        // Vértices 1 a N: Áreas cobertas
        for (int i = 1; i <= n; i++) {
            int x1 = fs.nextInt();
            int y1 = fs.nextInt();
            int x2 = fs.nextInt();
            int y2 = fs.nextInt();
            rects[i] = new Rect(x1, y1, x2, y2);
        }

        // Vértice N + 1: Ponto final
        int target = n + 1;
        rects[target] = new Rect(xf, yf, xf, yf);

        // Algoritmo de Dijkstra O(V^2)
        long[] dist = new long[totalNodes];
        boolean[] visited = new boolean[totalNodes];
        Arrays.fill(dist, Long.MAX_VALUE);

        dist[0] = 0;

        for (int i = 0; i < totalNodes; i++) {
            int u = -1;
            long minDist = Long.MAX_VALUE;

            for (int v = 0; v < totalNodes; v++) {
                if (!visited[v] && dist[v] < minDist) {
                    minDist = dist[v];
                    u = v;
                }
            }

            if (u == -1 || u == target) {
                break;
            }

            visited[u] = true;

            for (int v = 0; v < totalNodes; v++) {
                if (!visited[v]) {
                    long weight = rects[u].distTo(rects[v]);
                    if (dist[u] + weight < dist[v]) {
                        dist[v] = dist[u] + weight;
                    }
                }
            }
        }

        System.out.println(dist[target]);
    }
}
```

